import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UXD-047 — The launch draws the pad of its launch site and era","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-047-the-launch-draws-the-real-pad-of-its-site-and-era.md","filePath":"uxs/decisions/UXD-047-the-launch-draws-the-real-pad-of-its-site-and-era.md"}'),s={name:"uxs/decisions/UXD-047-the-launch-draws-the-real-pad-of-its-site-and-era.md"};function i(n,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="uxd-047-—-the-launch-draws-the-pad-of-its-launch-site-and-era" tabindex="-1">UXD-047 — The launch draws the pad of its launch site and era <a class="header-anchor" href="#uxd-047-—-the-launch-draws-the-pad-of-its-launch-site-and-era" aria-label="Permalink to &quot;UXD-047 — The launch draws the pad of its launch site and era&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit tests green, see Verification; renders read, see Not done)</li><li><strong>Date</strong>: 2026-11-15</li><li><strong>Decider</strong>: the operator, 2026-11-15 — &quot;Yes&quot; to plan row L58 (&quot;are our launch pads rendered as the real ones?&quot;), then &quot;we would add pads to colophon as 3D models&quot;</li><li><strong>Answers</strong>: L58 (G4)</li><li><strong>Builds on</strong>: <a href="./UXD-046-the-launch-runs-a-seeded-camera-director">UXD-046</a> (the launch director and its conditions rig), RFC-034 §7</li><li><strong>Changes</strong>: <code>src/lib/launches/pad-family.ts</code>, <code>pad-gallery.json</code>, <code>launch-instant.ts</code>, <code>src/lib/three/launch-pads.ts</code>, <code>launch-conditions-scene.ts</code>, <code>launch-director-rig.ts</code>, <code>LaunchScene.svelte</code>, <code>/fly</code> <code>+page.svelte</code>, <code>/dev/models</code>, <code>scripts/build-original-work.mjs</code> (the /colophon list)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Every launch drew one generic lattice tower scaled to the vehicle; only the ground under it was real (the 12 EOX Sentinel-2 site crops). A Saturn V and a Soyuz stood beside the same tower.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Sixteen pad models in five families</strong>, in the same low-detail style as the tower (boxes and cylinders, four materials, merged per material so a pad is a handful of draw calls): apollo-shuttle (Launch Umbilical Tower, Shuttle Fixed and Rotating Service Structures, SLS Mobile Launcher with lightning towers), soviet (the R-7 pad with four support arms, the Proton service tower), spacex (the transporter-erector at 39A, SLC-40 with and without the crew tower, SLC-4E, Starbase), ula (SLC-41), service-tower (Cape mobile-service-tower pads, Kourou ELA-2/3 and ELA-4, the Chinese service towers, Tanegashima, Sriharikota).</li><li><strong>True scale against the vehicle.</strong> The pad is built in metres and scaled by the vehicle&#39;s drawn length over its real height, so a tower stands at its real height relative to the rocket (the LUT at 1.05 times a Saturn V).</li><li><strong>The pad comes from the launch-site fleet record and the launch year.</strong> <code>src/lib/launches/pad-family.ts</code> maps every launch-site fleet record to an era rule (a test lists the directory, so a new record must get a row): LC-39A is the Apollo tower before 1976, the Shuttle structures to 2011, the Falcon pad after; SLC-40 is the Cape tower before 2010, the bare transporter-erector to 2022, the crew tower from 2023; SLC-41 is the Atlas pad from 2002. The pad of the mission&#39;s launch-site ref, else the launches entry&#39;s, else the profile&#39;s site name. A site with no row (twelve of 42) keeps the generic tower.</li><li><strong>Moving parts are a pure function of the mission time</strong>: the Soviet support arms fall outward over 3.2 s from T+0, the Apollo and tower swing arms swing away after T+0, the Falcon strongback leans 1.5 degrees before liftoff and 45 degrees at it. Scrubbing and pausing never jump.</li><li><strong>/colophon lists each pad model</strong> as one of the site&#39;s 3D models next to the spacecraft and launchers (thumbnails from the <code>/dev/models</code> gallery), with its sources and which sizes are approximate.</li></ol><h2 id="not-done-here" tabindex="-1">Not done here <a class="header-anchor" href="#not-done-here" aria-label="Permalink to &quot;Not done here&quot;">​</a></h2><ul><li>Dimensions are verified only for the LC-39 figures (LUT 380 ft, Mobile Launcher 160 x 135 x 25 ft, flame trench 43 x 59 x 449 ft, water tower 290 ft, 350 ft for the 39A tower) and the Falcon strongback motion (Wikipedia, plain dimensions); every other height is an approximation from general knowledge, listed in the search backlog for agency pages. No reference photograph was fetched.</li><li>No Vertical Integration Facility, mobile service tower in its parked position (except Ariane 6 and Sriharikota), crawler way, propellant spheres or catenary wires.</li><li>Frame time on a real GPU.</li></ul>',8)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
